const https = require('https');

function queryApi(params) {
  return new Promise((resolve, reject) => {
    const url = 'https://commons.wikimedia.org/w/api.php?' + new URLSearchParams(params).toString();
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' } }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(e);
        }
      });
    }).on('error', reject);
  });
}

async function test() {
  const tests = [
    { name: 'Featured (incategory)', q: 'incategory:"Featured_videos"' },
    { name: 'Featured (deepcat)', q: 'filetype:video deepcat:"Featured_videos"' },
    { name: 'All Videos', q: 'filetype:video' },
    { name: 'Nature', q: 'filetype:video nature' },
    { name: 'Timelapse', q: 'filetype:video timelapse' },
    { name: 'Animation', q: 'filetype:video animation' },
    { name: 'Science', q: 'filetype:video science' },
    { name: 'Astronomy', q: 'filetype:video astronomy' },
    { name: 'Wildlife', q: 'filetype:video wildlife' }
  ];

  for (const t of tests) {
    const resPage1 = await queryApi({
      action: 'query',
      generator: 'search',
      gsrnamespace: '6',
      gsrsearch: t.q,
      gsrlimit: '20',
      gsroffset: '0',
      format: 'json'
    });
    const count1 = Object.keys(resPage1.query?.pages || {}).length;

    const resPage2 = await queryApi({
      action: 'query',
      generator: 'search',
      gsrnamespace: '6',
      gsrsearch: t.q,
      gsrlimit: '20',
      gsroffset: '20',
      format: 'json'
    });
    const count2 = Object.keys(resPage2.query?.pages || {}).length;

    console.log(`[${t.name}] Query: ${t.q} -> P1: ${count1}, P2: ${count2}, Total hits hint:`, resPage1.continue ? 'has more' : 'end');
  }
}

test().catch(console.error);

