  for (const page of [1, 2, 3]) {
    const offset = (page - 1) * 20;
    const url = 'https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrnamespace=6&gsrsearch=' + encodeURIComponent(cat.q) + '&gsrlimit=20&gsroffset=' + offset + '&prop=imageinfo&iiprop=url|size|mime&iiurlwidth=600&format=json';
    const res = spawnSync('curl', ['-s', '-A', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)', url], { encoding: 'utf8' });
    try {
      const data = JSON.parse(res.stdout);
      const count = Object.keys(data.query?.pages || {}).length;
      console.log(`[${cat.name}] Page ${page} (offset=${offset}): ${count} items`);
    } catch (e) {
      console.log(`[${cat.name}] Page ${page} ERROR:`, e.message);
    }
  }
}

